mapper.select:
SELECT id,name,city,country,address,open_time,adult_ticket_price,child_ticket_price,longitude,latitude,phone,description,stars,rating,tags,ai.image AS mainImage
FROM attraction LEFT JOIN attraction_image AS ai ON  ai.attraction_id = id AND ai.sort_order = 1

    AND name LIKE CONCAT('%', #{keyword}, '%')
    AND city = #{city}

        AND (

            FIND_IN_SET(#{tag}, tags) > 0

        )

    AND stars = #{stars}

SELECT id,name,city,address,open_time,adult_ticket_price AS price,stars,rating,tags,ai.image AS image
FROM attraction LEFT JOIN attraction_image AS ai ON  ai.attraction_id = id AND ai.sort_order = 1

    AND city = #{city}
